    # Admin panel for shop_sets. The HTML shell is admin-gated too so the
    # endpoint map and client-side control surface are not exposed anonymously.
    async def extra_shop_admin(request: web.Request) -> web.FileResponse:
        user_id = await require_user_id(request)
        if not await _is_admin_user(db, user_id):
            raise web.HTTPForbidden(
                reason="admin_access_required",
                text='{"error":"admin_access_required"}',
                content_type="application/json",
            )
        path = EXTRA_SHOP_DIR / "admin.html"
        if not path.exists():
            raise web.HTTPNotFound(text="admin.html not found")
        response = web.FileResponse(
            path,
            headers={
                "Cache-Control": "no-store, must-revalidate",
                "Referrer-Policy": "no-referrer",
                "X-Content-Type-Options": "nosniff",
                "Content-Security-Policy": (
                    "default-src 'self'; "
                    "script-src 'self' 'unsafe-inline'; "
                    "style-src 'self' 'unsafe-inline'; "
                    "img-src 'self' data: blob: https:; "
                    "connect-src 'self'; "
                    "base-uri 'none'; "
                    "frame-ancestors 'self' https://web.telegram.org"
                ),
            },
        )
        _set_admin_session_cookie(request, response, user_id)
        return response

    app.router.add_get("/extraShop/admin", extra_shop_admin)
    app.router.add_get("/extraShop/admin/", extra_shop_admin)

    # POST /api/payments/checkout/public/start — публичный магазин без Telegram WebApp auth

    def _normalize_checkout_item_data(data: dict[str, Any]) -> dict[str, Any]:
        """Keep only product selectors from legacy client metadata, never prices or rewards."""
        normalized = dict(data or {})
        metadata = data.get("metadata") if isinstance(data, dict) else None
        if isinstance(metadata, dict):
            for key in ("product_code", "item_type", "package_type", "recipient_id", "ultra"):
                if not normalized.get(key) and metadata.get(key) is not None:
                    normalized[key] = metadata.get(key)
        return normalized

    async def _resolve_ruble_checkout_item(
        db: Database,
        *,
        user_id: int,
        data: dict[str, Any],
    ) -> dict[str, Any]:
        """Валидация рублевого товара и сбор metadata.

        Сначала ищет товар в ruble_products (по product_code или item_type+package_type),
        затем fallback на старый hardcoded config.
        Возвращает {"item_type", "item_name", "amount_rub", "metadata"} при успехе,
        либо {"error": "код", "message": "текст", "status": http_code} при ошибке.
        """
        from infrastructure.shop_config import GEM_PACKAGES

        item_type = str(data.get("item_type", "") or "")
        package_type = str(data.get("package_type", "") or "")
        product_code = str(data.get("product_code", "") or "")
        recipient_id_raw = data.get("recipient_id")

        metadata: dict[str, Any] = {"user_id": user_id, "item_type": item_type}
        item_name: str = ""
        amount_rub: float = 0.0

        # 1. Try DB ruble_products
        db_product = None
        if product_code:
            db_product = await db.get_ruble_product(product_code)
            if db_product and not db_product.get("is_active", True):
                return {
                    "error": "product_inactive",
                    "message": "Товар временно недоступен",
                    "status": 400,
                }
        if not db_product and item_type:
            # Try matching by item_type + package_type
            all_products = await db.get_ruble_products(active_only=False)
            matching_products = [
                p for p in all_products
                if p["item_type"] == item_type and (not package_type or p.get("package_type") == package_type)
            ]
            db_product = next((p for p in matching_products if p.get("is_active", True)), None)
            if not db_product and matching_products:
                return {
                    "error": "product_inactive",
                    "message": "Товар временно недоступен",
                    "status": 400,
                }

        if db_product and db_product.get("is_active", True):
            product_currency = str(db_product.get("currency") or "rubles")
            if product_currency != "rubles":
                return {"error": "product_currency_not_rubles", "message": "Товар не продаётся за рубли", "status": 400}
            amount_rub = float(db_product.get("price", 0))
            db_item_type = str(db_product.get("item_type") or item_type)
            db_package_type = db_product.get("package_type")
            shop_set_id = db_product.get("shop_set_id")
            if db_item_type == "gift_shop_set":
                return {
                    "error": "gift_checkout_forbidden",
                    "message": "Подарочный набор доступен только через бесплатное получение.",
                    "status": 400,
                }
            if db_item_type == "gems_package":
                package_text = str(db_package_type or "").strip()
                if not package_text or package_text not in GEM_PACKAGES:
                    return {"error": "invalid_package_type", "message": "Некорректный пакет гемов", "status": 400}
                if GEM_PACKAGES[package_text].get("one_time"):
                    settings = await db.get_user_settings(user_id)
                    if settings and settings.get("starter_pack_used"):
                        return {"error": "already_used", "message": "Стартовый пакет уже куплен", "status": 400}
            if db_item_type == "shop_set":
                if not shop_set_id:
                    return {"error": "shop_set_id_required", "message": "Для товара не указан набор", "status": 400}
                set_data = await db.get_shop_set(int(shop_set_id))
                if not set_data:
                    return {"error": "set_not_found", "message": "Набор не найден", "status": 404}
                if not set_data.get("is_active", True):
                    return {"error": "set_inactive", "message": "Набор недоступен", "status": 400}
                if set_data.get("currency") != "rubles":
                    return {"error": "set_currency_not_rubles", "message": "Набор не продаётся за рубли", "status": 400}
                get_claimed_sets = getattr(db, "get_claimed_shop_set_ids", None)
                if get_claimed_sets and int(shop_set_id) in await get_claimed_sets(user_id):
                    return {"error": "already_claimed", "message": "Набор уже получен", "status": 409}
                rewards_data = set_data.get("rewards") or []
                if hasattr(db, "validate_shop_set_rewards"):
                    _rewards, rewards_error = await db.validate_shop_set_rewards(rewards_data)
                    if rewards_error:
                        return {"error": rewards_error, "message": "Набор содержит недоступные награды", "status": 400}
                elif hasattr(db, "_normalize_shop_set_rewards"):
                    _rewards, rewards_error = db._normalize_shop_set_rewards(rewards_data)
                    if rewards_error:
                        return {"error": rewards_error, "message": "Набор не содержит выдаваемых наград", "status": 400}
                elif not isinstance(rewards_data, list) or not rewards_data:
                    return {"error": "empty_rewards", "message": "Набор не содержит выдаваемых наград", "status": 400}
            if db_item_type == "shop_set" and shop_set_id:
                db_item_type = f"shop_set_{int(shop_set_id)}"

            item_type = db_item_type
            package_type = str(db_package_type or "")
            item_name = str(db_product.get("name", "") or item_type)
            metadata.update({
                "product_code": db_product.get("code"),
                "item_type": item_type,
                "package_type": package_type or None,
                "item_name": item_name,
                "amount_rub": amount_rub,
            })
            safe_image_url = _safe_ruble_product_image_url(db_product.get("image_url"))
            if safe_image_url:
                metadata["image_url"] = safe_image_url
            if shop_set_id:
                metadata["shop_set_id"] = int(shop_set_id)
            if package_type:
                metadata["package_type"] = package_type
                # For gems_package, infer gems count from config or metadata
                if item_type == "gems_package":
                    pkg_cfg = GEM_PACKAGES.get(package_type)
                    if pkg_cfg:
                        metadata["package_gems"] = int(pkg_cfg["gems"])
                    metadata["starter"] = (package_type == "starter_once")
                    if package_type == "starter_once":
                        metadata["one_time_product"] = True
                        metadata["product_key"] = "gems_package:starter_once"

        # 2. Fallback: legacy hardcoded types
        elif item_type == "gems_package":
            if not package_type:
                return {"error": "missing_package_type", "message": "package_type required for gems_package", "status": 400}
            pkg = GEM_PACKAGES.get(package_type)
            if not pkg:
                return {"error": "unknown_package_type", "message": f"Неизвестный пакет: {package_type}", "status": 400}
            if pkg.get("one_time"):
                settings = await db.get_user_settings(user_id)
                if settings and settings.get("starter_pack_used"):
                    return {"error": "already_used", "message": "Стартовый пакет уже куплен", "status": 400}
            gems_count = int(pkg["gems"])
            amount_rub = float(pkg["price"])
            item_name = f"{gems_count} гемов"
            if pkg.get("one_time"):
                item_name += " (стартовый)"
            metadata.update({
                "package_type": package_type,
                "package_gems": gems_count,
                "amount_rub": amount_rub,
                "item_name": item_name,
                "starter": package_type == "starter_once",
            })
            if package_type == "starter_once":
                metadata["one_time_product"] = True
                metadata["product_key"] = "gems_package:starter_once"

        elif item_type == "extrapass":
            amount_rub = 179.0
            item_name = "ExtraPass на 1 сезон"
            metadata.update({"item_name": item_name, "amount_rub": amount_rub})

        elif item_type == "extrapass_ultra":
            amount_rub = 349.0
            item_name = "ExtraPass Ultra на 1 сезон"
            metadata.update({"item_name": item_name, "amount_rub": amount_rub})

        elif item_type == "extrapass_gift":
            recipient_id = int(recipient_id_raw) if recipient_id_raw else 0
            if not recipient_id or recipient_id <= 0:
                return {"error": "missing_recipient", "message": "recipient_id required for gift", "status": 400}
            gift_ultra = str(data.get("ultra", "") or "").lower() in {"1", "true", "yes"}
            amount_rub = 349.0 if gift_ultra else 179.0
            item_name = ("Ultra " if gift_ultra else "") + "ExtraPass (подарок)"
            metadata.update({
                "item_name": item_name,
                "amount_rub": amount_rub,
                "recipient_id": recipient_id,
                "ultra": gift_ultra,
            })

        elif item_type == "starter_boost":
            amount_rub = 499.0
            item_name = "Starter Boost"
            metadata.update({"item_name": item_name, "amount_rub": amount_rub})

        elif item_type == "squad_boost":
            amount_rub = 299.0
            item_name = "Boost сквада"
            metadata.update({"item_name": item_name, "amount_rub": amount_rub, "product_code": "squad_boost"})

        elif item_type.startswith("shop_set_"):
            try:
                set_id = int(item_type.split("_")[-1])
            except (ValueError, IndexError):
                return {"error": "invalid_set_id", "status": 400}
            set_data = await db.get_shop_set(set_id)
            if not set_data:
                return {"error": "set_not_found", "status": 404}
            if not set_data.get("is_active"):
                return {"error": "set_inactive", "message": "Набор недоступен", "status": 400}
            if set_data.get("currency") != "rubles":
                return {"error": "set_currency_not_rubles", "message": "Набор не продаётся за рубли", "status": 400}
            get_claimed_sets = getattr(db, "get_claimed_shop_set_ids", None)
            if get_claimed_sets and set_id in await get_claimed_sets(user_id):
                return {"error": "already_claimed", "message": "Набор уже получен", "status": 409}
            amount_rub = float(set_data.get("price", 0))
            item_name = str(set_data.get("name", "") or f"Набор #{set_id}")
            metadata.update({
                "item_name": item_name,
                "amount_rub": amount_rub,
                "shop_set_id": set_id,
            })

        elif item_type == "gift_shop_set":
            return {
                "error": "gift_checkout_forbidden",
                "message": "Подарочный набор доступен только через бесплатное получение.",
                "status": 400,
            }

        else:
            return {"error": "unknown_item_type", "message": f"Неизвестный тип товара: {item_type}", "status": 400}

        if amount_rub <= 0:
            return {"error": "invalid_amount", "status": 400}

        return {
            "item_type": item_type,
            "item_name": item_name,
            "amount_rub": amount_rub,
            "metadata": metadata,
        }

    def _one_time_product_key(metadata: dict[str, Any]) -> str:
        if not isinstance(metadata, dict) or not metadata.get("one_time_product"):
            return ""
        return str(metadata.get("product_key") or "").strip()

    async def _reserve_one_time_payment_or_response(
        *,
        user_id: int,
        metadata: dict[str, Any],
        provider: str,
        checkout_jti: str | None = None,
    ) -> web.Response | None:
        product_key = _one_time_product_key(metadata)
        if not product_key:
            return None
        reserve = getattr(db, "reserve_one_time_payment", None)
        if not reserve:
            return None
        reservation_id = str(metadata.get("one_time_reservation_id") or uuid.uuid4())
        metadata["one_time_reservation_id"] = reservation_id
        result = await reserve(
            user_id=user_id,
            product_key=product_key,
            reservation_id=reservation_id,
            checkout_jti=checkout_jti,
            provider=provider,
            expires_at=datetime.now(timezone.utc) + timedelta(minutes=60),
        )
        if result.get("success"):
            return None
        error = str(result.get("error") or "starter_checkout_in_progress")
        status = 400 if error == "already_used" else 409
        message = "Стартовый пакет уже куплен" if error == "already_used" else "Оплата стартового пакета уже начата"
        return web.json_response({"error": error, "message": message}, status=status)

    async def _attach_one_time_payment_if_needed(
        *,
        user_id: int,
        metadata: dict[str, Any],
        payment_id: str,
        provider: str,
    ) -> None:
        product_key = _one_time_product_key(metadata)
        reservation_id = str(metadata.get("one_time_reservation_id") or "")
        attach = getattr(db, "attach_one_time_payment", None)
        if product_key and reservation_id and attach:
            await attach(
                user_id=user_id,
                product_key=product_key,
                reservation_id=reservation_id,
                payment_id=payment_id,
                provider=provider,
            )

    async def _release_one_time_payment_if_needed(*, user_id: int, metadata: dict[str, Any]) -> None:
        product_key = _one_time_product_key(metadata)
        reservation_id = str(metadata.get("one_time_reservation_id") or "")
        release = getattr(db, "release_one_time_payment_reservation", None)
        if product_key and reservation_id and release:
            await release(user_id=user_id, product_key=product_key, reservation_id=reservation_id)

    async def _wait_for_checkout_payment(checkout_jti: str) -> dict[str, Any] | None:
        # Ждём, пока параллельная попытка создания платежа завершится.
        # Увеличено с 0.3s (30 * 10ms) до 5s (100 * 50ms), так как
        # HTTP-вызовы к YooKassa/Robokassa могут занимать несколько
        # секунд и предыдущая попытка оказывалась обрезана 409.
        for _ in range(100):
            await asyncio.sleep(0.05)
            existing = await db.get_checkout_session(checkout_jti)
            if existing and existing.get("payment_id") and existing.get("confirmation_url"):
                return existing
        return None

    async def _checkout_confirmation_url_for_existing_payment(
        payment_id: Any,
        confirmation_url: Any,
    ) -> str:
        pid = str(payment_id or "")
        url = str(confirmation_url or "")
        if not pid.startswith("robokassa_") or not url:
            return url
        try:
            parsed = urlsplit(url)
        except ValueError:
            parsed = None
        if parsed and parsed.netloc == "auth.robokassa.ru":
            return url
        if parsed and "/api/payments/robokassa/pay/" not in parsed.path:
            return url
        if parsed and "/api/payments/robokassa/pay/" in parsed.path:
            return url

        payment = await db.get_payment_by_id(pid)
        metadata = payment.get("metadata") if isinstance(payment, dict) else None
        if isinstance(metadata, str):
            try:
                metadata = _stdlib_json.loads(metadata)
            except Exception:
                metadata = None
        if not isinstance(metadata, dict):
            return url
        form = metadata.get("robokassa_form")
        if not isinstance(form, dict) or not form.get("SignatureValue"):
            return url
        action = str(metadata.get("robokassa_form_action") or "")
        if not action:
            service = app.get("robokassa_payment_service")
            action = str(getattr(getattr(service, "settings", None), "payment_url", "") or "")
        if not action:
            action = "https://auth.robokassa.ru/Merchant/Index.aspx"
        sanitized_form = {str(key): str(value) for key, value in form.items() if value is not None}
        return f"{action}?{urlencode(sanitized_form)}"

    async def checkout_public_start_handler(request: web.Request) -> web.Response:
        logger = logging.getLogger(__name__)

        if request.method != "POST":
            return web.json_response({"error": "method_not_allowed"}, status=405)

        try:
            data = await request.json()
            telegram_id_raw = data.get("telegram_id") or data.get("recipient_id")
            if not telegram_id_raw:
                return web.json_response(
                    {"error": "missing_telegram_id", "message": "Укажите Telegram ID для зачисления"},
                    status=400,
                )

            try:
                user_id = int(str(telegram_id_raw).strip())
            except (ValueError, TypeError):
                return web.json_response(
                    {"error": "invalid_telegram_id", "message": "Telegram ID должен быть числом"},
                    status=400,
                )

            if user_id <= 0:
                return web.json_response(
                    {"error": "invalid_telegram_id", "message": "Telegram ID должен быть положительным числом"},
                    status=400,
                )

            user_exists = await db.fetchval("SELECT 1 FROM users WHERE user_id = $1", user_id)
            if not user_exists:
                return web.json_response({
                    "error": "user_not_found",
                    "message": "Сначала откройте игру ExtraArena в Telegram хотя бы один раз.",
                }, status=404)

            secret = request.app["bot_token"]

            resolved = await _resolve_ruble_checkout_item(db, user_id=user_id, data=data)
            if "error" in resolved:
                return web.json_response(
                    {"error": resolved["error"], "message": resolved.get("message", "")},
                    status=resolved.get("status", 400),
                )

            item_type = resolved["item_type"]
            item_name = resolved["item_name"]
            amount_rub = resolved["amount_rub"]
            metadata = resolved["metadata"]
            if _one_time_product_key(metadata):
                return web.json_response(
                    {
                        "error": "one_time_public_checkout_forbidden",
                        "message": "Разовый товар можно купить только внутри авторизованного WebApp.",
                    },
                    status=403,
                )

            now = datetime.now(timezone.utc)
            expires_at = now + timedelta(minutes=60)
            jti = str(uuid.uuid4())

            payload = {
                "user_id": user_id,
                "item_type": item_type,
                "item_name": item_name,
                "amount_rub": amount_rub,
                "metadata": metadata,
                "exp": int(expires_at.timestamp()),
                "iat": int(now.timestamp()),
                "jti": jti,
            }

            metadata["checkout_jti"] = jti
            reservation_response = await _reserve_one_time_payment_or_response(
                user_id=user_id,
                metadata=metadata,
                provider="checkout",
                checkout_jti=jti,
            )
            if reservation_response is not None:
                return reservation_response

            session_result = await db.create_checkout_session(
                checkout_jti=jti,
                user_id=user_id,
                item_type=item_type,
                amount=amount_rub,
                metadata=metadata,
                expires_at=expires_at,
            )
            if not session_result.get("success"):
                await _release_one_time_payment_if_needed(user_id=user_id, metadata=metadata)
                logger.error("Не удалось создать checkout session %s: %s", jti, session_result.get("error"))
                return web.json_response(
                    {"error": "checkout_session_failed", "message": "Не удалось создать сессию оплаты"},
                    status=500,
                )

            payload_json = _stdlib_json.dumps(payload, separators=(",", ":"), ensure_ascii=True, sort_keys=True)
            payload_b64 = base64.urlsafe_b64encode(payload_json.encode()).rstrip(b"=").decode()
            signature = hmac.new(secret.encode(), payload_b64.encode(), "sha256").hexdigest()

            token = f"{payload_b64}.{signature}"

            logger.info("Public checkout started: user=%s item=%s amount=%.2f token=%s", user_id, item_type, amount_rub, payload["jti"])

            extra_shop_url = request.app.get("extra_shop_url", request.app.get("webapp_url", ""))
            return web.json_response({
                "success": True,
                "checkout_url": f"{extra_shop_url.rstrip('/')}/extraShop#checkout_jti={payload['jti']}",
                "checkout_jti": payload["jti"],
            })

        except Exception as e:
            logger.error("Ошибка checkout_public_start: %s", e, exc_info=True)
            return web.json_response({"error": "internal_server_error", "message": str(e)}, status=500)

    # POST /api/payments/checkout/start — валидация товара и создание checkout-токена
